19	static void require(bool Assertion, const char *Msg, llvm::StringRef Code) {
20	  if (!Assertion) {
21	    llvm::errs() << "Annotated testcase: " << Msg << "\n" << Code << "\n";
22	    llvm_unreachable("Annotated testcase assertion failed!");
23	  }
24	}
